function Roles(){const permissions=["Dashboard","Orders","Catalog","Pricing","Customers","Content","Production","Reports","Settings"];return <div className="roles-grid"><section className="panel role-list"><PanelHead title="Roles" note="7 roles"/>{[["Super Administrator","3 users"],["Catalog Manager","2 users"],["Order Manager","4 users"],["Atelier Production","8 users"],["Content Editor","2 users"]].map((x,i)=><button className={i===1?"active":""} key={x[0]}><i>{x[0].split(" ").map(v=>v[0]).join("")}</i><span><b>{x[0]}</b><small>{x[1]}</small></span><em>›</em></button>)}</section><section className="panel permission-panel"><div className="editor-head"><div><span>ROLE</span><h2>Catalog Manager</h2></div><button>Save permissions</button></div><p>Control what this role can view and change across the administration.</p><div className="permission-table"><header><b>MODULE</b><span>VIEW</span><span>CREATE</span><span>EDIT</span><span>DELETE</span><span>EXPORT</span></header>{permissions.map((p,i)=><div key={p}><b>{p}</b>{Array.from({length:5},(_,j)=><input key={j} type="checkbox" defaultChecked={(i<4&&j<3)||(i===5&&j<2)}/>)}</div>)}</div></section></div>}

function Analytics({kind}:{kind:string}){return <><section className="metric-grid analytics-metrics">{(kind==="sales"?[["GROSS SALES","₹21.8L","+14.2%"],["NET REVENUE","₹18.42L","+12.4%"],["GROSS MARGIN","62.8%","+2.1%"],["CONVERSION","3.84%","+0.6%"]]:[["SWATCH REQUESTS","1,248","+18.4%"],["SAMPLE → ORDER","24.6%","+4.1%"],["TOP FABRIC","Oatmeal Linen","182 orders"],["TOP COLOUR","Natural","38% share"]]).map((x,i)=><article key={x[0]}><span>{x[0]}</span><strong>{x[1]}</strong><small className="up">{x[2]}</small><em style={{width:`${55+i*9}%`}}/></article>)}</section><div className="dashboard-grid"><section className="panel revenue-panel"><PanelHead title={kind==="sales"?"Revenue trend":"Swatch demand trend"} note="Sep 01—29"/><div className="bar-chart">{[42,56,48,72,62,86,75,91,78,96,83,100].map((h,i)=><i key={i} style={{height:`${h}%`}}><em/></i>)}</div><div className="bar-labels"><span>Week 1</span><span>Week 2</span><span>Week 3</span><span>Week 4</span></div></section><section className="panel"><PanelHead title={kind==="sales"?"Top categories":"Top requested fabrics"} note="By contribution"/>{["Custom Drapery","Bedding","Roman Shades","Hardware","Swatches"].map((x,i)=><div className="rank-row" key={x}><b>0{i+1}</b><span>{x}<i><em style={{width:`${88-i*13}%`}}/></i></span><strong>{["₹8.4L","₹4.2L","₹3.6L","₹1.4L","₹82K"][i]}</strong></div>)}</section></div></>}

function Settings({kind,act}:{kind:string;act:(x:string)=>void}){return <div className="settings-layout"><nav className="panel settings-nav">{["General","Brand identity","Regional","Checkout","Policies","Advanced"].map((x,i)=><button className={i===0?"active":""} key={x}>{x}<span>›</span></button>)}</nav><form className="panel settings-form" onSubmit={e=>{e.preventDefault();act("Settings saved")}}><div className="editor-head"><div><span>{kind.toUpperCase()}</span><h2>{kind==="store"?"General store information":kind==="payments"?"Payment configuration":"Email & notification defaults"}</h2></div><button>Save changes</button></div><p>These settings define the default experience across the storefront and internal operations.</p><div className="form-row"><label>Store name<input defaultValue="India Home Furnishings"/></label><label>Legal business name<input defaultValue="India Home Furnishings Pvt. Ltd."/></label></div><label>Primary contact email<input defaultValue="concierge@indiahomefurnishings.com"/></label><div className="form-row"><label>Currency<select defaultValue="INR"><option>INR — Indian Rupee</option><option>USD — US Dollar</option></select></label><label>Timezone<select defaultValue="IST"><option>IST — Asia/Kolkata</option><option>GMT — London</option></select></label></div><h3>OPERATIONAL DEFAULTS</h3>{["Automatically archive fulfilled orders after 180 days","Require approval for pricing changes","Send daily operations summary"].map((x,i)=><div className="switch-row" key={x}><span><b>{x}</b><small>Recommended for a controlled production workflow.</small></span><input type="checkbox" defaultChecked={i<2}/></div>)}</form></div>}
